const lead = $('Lead Webhook').first().json;
let parsed = {};
try {
  const raw = $input.first().json.output || '';
  const match = raw.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(match ? match[0] : raw);
} catch (e) { parsed = {}; }
return [{ json: {
  name: lead.name || '',
  email: lead.email || '',
  company: lead.company || '',
  company_domain: lead.company_domain || '',
  score: typeof parsed.score === 'number' ? Math.max(0, Math.min(100, Math.round(parsed.score))) : 0,
  reason: typeof parsed.reason === 'string' ? parsed.reason : 'No reason returned'
}}];
